package yomikai.data.ui

import android.content.Context
import yomikai.data.ai.AiWorkspace
import kotlinx.coroutines.flow.MutableStateFlow
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.asStateFlow
import logcat.LogPriority
import yomikai.data.ui.UiTab
import yomikai.data.ui.UiTabs
import org.json.JSONArray
import org.json.JSONObject
import yomikai.core.common.util.system.logcat
import java.io.File

/**
 * Хранение скрытых вкладок нижней навигации.
 *
 * Один JSON-файл `workspace/ui/tabs.json` со списком id: переживает перезапуск,
 * уезжает с архивом workspace, создаётся файлом или через AI-чат
 * (`ui_tab_hide` / `ui_tab_show`). Исполняемого кода в нём нет — только id из
 * замкнутого списка [UiTab], поэтому плагин не может уронить приложение.
 *
 * Контракт надёжности тот же, что у [UiActionRegistry] и `AiProviders`: ни один
 * метод не бросает исключение наружу, битый JSON даёт пустой список, а запись
 * возвращает результат булевым значением.
 *
 * [version] растёт после каждой успешной записи, чтобы открытый `HomeScreen`
 * перечитал список сразу, без перезапуска приложения.
 */
object UiTabRegistry {

    private val versionState = MutableStateFlow(0)

    /** Счётчик записей: `HomeScreen` подписан на него и перечитывает файл. */
    val version: StateFlow<Int> = versionState.asStateFlow()

    private fun file(context: Context): File =
        File(File(AiWorkspace.root(context), "ui").apply { runCatching { mkdirs() } }, "tabs.json")

    /** Скрытые вкладки, нормализованные [UiTabs.sanitizeHidden]. */
    fun hidden(context: Context): Set<String> = UiTabs.sanitizeHidden(readHidden(context))

    private fun readHidden(context: Context): Set<String> = runCatching {
        val f = file(context)
        if (!f.isFile) return@runCatching emptySet()
        val array = JSONObject(f.readText()).optJSONArray("hidden") ?: JSONArray()
        buildSet {
            for (i in 0 until array.length()) {
                array.optString(i)?.trim()?.takeIf { it.isNotEmpty() }?.let { add(it) }
            }
        }
    }.getOrElse { e ->
        logcat(LogPriority.WARN, e) { "UiTabRegistry.hidden failed" }
        emptySet()
    }

    /** Скрыть вкладку. `false` — неизвестный id, закреплённая вкладка или сбой записи. */
    fun hide(context: Context, id: String): Boolean {
        val tab = UiTab.fromId(id)
        val error = UiTabs.validate(id)
        if (tab == null || error != null) {
            logcat(LogPriority.WARN) { "UiTabRegistry.hide rejected '$id': ${error ?: "unknown id"}" }
            return false
        }
        return write(context, hidden(context) + tab.id)
    }

    /** Вернуть вкладку. `false` — неизвестный id или сбой записи. */
    fun show(context: Context, id: String): Boolean {
        val tab = UiTab.fromId(id)
        if (tab == null) {
            logcat(LogPriority.WARN) { "UiTabRegistry.show rejected unknown id '$id'" }
            return false
        }
        return write(context, hidden(context) - tab.id)
    }

    /**
     * Записать список. Порядок в файле всегда канонический ([UiTabs.IDS]),
     * поэтому содержимое не «прыгает» от порядка добавления.
     */
    private fun write(context: Context, hidden: Set<String>): Boolean {
        val normalized = UiTabs.sanitizeHidden(hidden)
        return runCatching {
            val array = JSONArray()
            UiTabs.IDS.filter { it in normalized }.forEach { array.put(it) }
            file(context).writeText(JSONObject().put("hidden", array).toString(2))
            versionState.value++
            true
        }.getOrElse { e ->
            logcat(LogPriority.WARN, e) { "UiTabRegistry.write failed" }
            false
        }
    }
}

 *
 * Id стабильные и живут в файлах пользователя, поэтому их нельзя брать из имени
 * класса: в release-сборке R8 переименовывает классы. Порядок объявлений —
 * порядок вкладок в навигации.
 *
 * @param pinned вкладку нельзя скрыть: без неё приложение останется либо без
 *   контента ([LIBRARY]), либо без входа в настройки ([MORE]), и вернуть её
 *   будет нечем.
 */
enum class UiTab(val id: String, val title: String, val pinned: Boolean = false) {
    LIBRARY("library", "Библиотека", pinned = true),
    LOCAL_LIBRARY("local_library", "Локальная библиотека"),
    UPDATES("updates", "Обновления"),
    HISTORY("history", "История"),
    BROWSE("browse", "Каталоги"),
    BROWSER("browser", "Браузер"),
    AI("ai", "AI-чат"),
    SCREENSHOTS("screenshots", "Скриншоты"),
    MORE("more", "Ещё", pinned = true),
    ;

    companion object {
        fun fromId(id: String?): UiTab? =
            entries.firstOrNull { it.id == id?.trim()?.lowercase() }
    }
}

/**
 * Правила видимости вкладок: чистые функции без Android, чтобы их можно было
 * проверить юнит-тестами.
 */
object UiTabs {

    /** Все id в порядке показа. */
    val IDS: List<String> = UiTab.entries.map { it.id }

    /** Id, которые нельзя скрыть ни через чат, ни правкой файла. */
    val PROTECTED_IDS: Set<String> = UiTab.entries.filter { it.pinned }.map { it.id }.toSet()

    /**
     * Причина, по которой id не годится, или `null`, если годится.
     *
     * Текст причины показывается пользователю и агенту, поэтому он всегда
     * содержит список допустимых значений.
     */
    fun validate(id: String): String? {
        val key = id.trim().lowercase()
        return when {
            key.isEmpty() -> "Пустой id вкладки"
            key !in IDS -> "Неизвестная вкладка «$key». Доступны: ${IDS.joinToString()}"
            key in PROTECTED_IDS ->
                "Вкладку «$key» нельзя скрыть: без неё не останется библиотеки или входа в настройки"
            else -> null
        }
    }

    /** Скрыта ли вкладка. Закреплённые не скрываются никогда. */
    fun isHidden(id: String, hidden: Set<String>): Boolean {
        val key = id.trim().lowercase()
        return key in hidden && key !in PROTECTED_IDS
    }

    /**
     * Оставить только видимые вкладки, сохранив порядок [ids].
     *
     * Защита применяется и здесь: файл `workspace/ui/tabs.json` пользователь
     * может править руками или залить из архива чужого workspace.
     */
    fun visibleTabs(ids: List<String>, hidden: Set<String>): List<String> =
        ids.filterNot { isHidden(it, hidden) }

    /** Выкинуть неизвестные, закреплённые и пустые id, привести к нижнему регистру. */
    fun sanitizeHidden(ids: Collection<String>): Set<String> =
        ids.map { it.trim().lowercase() }
            .filter { it in IDS && it !in PROTECTED_IDS }
            .toSet()
}

